import React, { useState, useCallback } from "react";
import { Timeline, FlowbiteTimelineTheme } from "flowbite-react";
import { FlowbiteTimelinePointTheme } from "flowbite-react/lib/esm/components/Timeline/TimelinePoint";
import { FlowbiteTimelineContentTheme } from "flowbite-react/lib/esm/components/Timeline/TimelineContent";
import { FlowbiteTimelineItemTheme } from "flowbite-react/lib/esm/components/Timeline/TimelineItem";
import { LiveInfo } from "../../../types/live";
import EnhancedLiveTimelineItem from "./enhanced-timeline-item";
import { useDict } from "../../../i18n/site/SiteLangContext";

interface LiveProps {
  data: LiveInfo[];
}

const timelinePointTheme: FlowbiteTimelinePointTheme = {
  horizontal: "flex items-center",
  line: "hidden h-0.5 w-full bg-bx-line sm:flex",
  marker: {
    base: {
      horizontal:
        "absolute -left-1.5 h-3 w-3 rounded-full border border-bx-line bg-bx-line",
      vertical:
        "absolute -left-1.5 mt-1.5 h-3 w-3 rounded-full border border-bx-line bg-bx-line",
    },
    icon: {
      base: "h-3 w-3 text-bx-blue",
      wrapper:
        "absolute -left-3 flex h-6 w-6 items-center justify-center rounded-full bg-bx-blueDeep ring-8 ring-bx-bg",
    },
  },
  vertical: "",
};

const timelineContentTheme: FlowbiteTimelineContentTheme = {
  root: {
    base: "mt-3 sm:pr-8",
  },
  body: "mb-2 text-sm font-normal text-bx-ink",
  time: "mb-1 text-xs font-normal leading-none text-bx-ink2",
  title: "text-base font-semibold text-bx-ink",
};

const timelineItemTheme: FlowbiteTimelineItemTheme = {
  root: {
    horizontal: "relative mb-6 sm:mb-0",
    vertical: "mb-4 ml-6",
  },
  content: timelineContentTheme,
  point: timelinePointTheme,
};

const timelineRootTheme: FlowbiteTimelineTheme = {
  root: {
    direction: {
      horizontal: "items-base sm:flex",
      vertical: "relative border-l border-bx-line",
    },
  },
  item: timelineItemTheme,
};

const tags = {
  name: ["Reol", "REOL", "れをる"],
  year: [
    "2026",
    "2025",
    "2024",
    "2023",
    "2022",
    "2021",
    "2020",
    "2019",
    "2018",
    "2017",
    "2016",
    "2015",
    "2014",
  ],
  type: ["event", "oneman"],
};

const Live: React.FC<LiveProps> = ({ data }) => {
  const t = useDict().live;
  const [currentList, setCurrentList] = useState<LiveInfo[]>(data);
  const [currentNames, setCurrentNames] = useState<string[]>([]);
  const [currentYears, setCurrentYears] = useState<string[]>([]);
  const [currentTypes, setCurrentTypes] = useState<string[]>([]);

  const toggleTag = useCallback(
    (currentList: string[], target: string): string[] => {
      if (currentList.includes(target)) {
        return currentList.filter((item) => item !== target);
      } else {
        return [...currentList, target];
      }
    },
    []
  );

  const filterNextList = useCallback(
    (
      nextNames?: string[],
      nextYears?: string[],
      nextTypes?: string[]
    ): LiveInfo[] => {
      let list = data;
      if (nextNames && nextNames.length > 0) {
        list = list.filter((item) => nextNames.includes(item?.name ?? ""));
      }
      if (nextYears && nextYears.length > 0) {
        list = list.filter(
          (item) =>
            (
              item?.date
                .match(/[0-9]{4}/g)
                ?.filter((year) => nextYears.includes(year)) ?? []
            ).length > 0
        );
      }
      if (nextTypes && nextTypes.length > 0) {
        list = list.filter((item) => nextTypes.includes(item?.type ?? ""));
      }

      return list;
    },
    [data]
  );

  const handleNameTagClick = useCallback(
    (tag: string) => {
      const nextNames = toggleTag(currentNames, tag);
      setCurrentNames(nextNames);
      setCurrentList(filterNextList(nextNames, currentYears, currentTypes));
    },
    [currentNames, currentYears, currentTypes, toggleTag, filterNextList]
  );

  const handleYearTagClick = useCallback(
    (tag: string) => {
      const nextYears = toggleTag(currentYears, tag);
      setCurrentYears(nextYears);
      setCurrentList(filterNextList(currentNames, nextYears, currentTypes));
    },
    [currentNames, currentYears, currentTypes, toggleTag, filterNextList]
  );

  const handleTypeTagClick = useCallback(
    (tag: string) => {
      const nextTypes = toggleTag(currentTypes, tag);
      setCurrentTypes(nextTypes);
      setCurrentList(filterNextList(currentNames, currentYears, nextTypes));
    },
    [currentNames, currentYears, currentTypes, toggleTag, filterNextList]
  );

  // 年ごとにグループ化(降順)。開催日は範囲表記("2026-03-14〜2026-07-18")の
  // こともあるため、文字列中の最初の4桁を開始年として使う
  const groupedByYear = React.useMemo(() => {
    const grouped = new Map<string, LiveInfo[]>();
    for (const live of currentList) {
      const year = live.date?.match(/\d{4}/)?.[0] || t.unknownYear;
      if (!grouped.has(year)) grouped.set(year, []);
      grouped.get(year)!.push(live);
    }
    const sortedYears = Array.from(grouped.keys()).sort((a, b) =>
      b.localeCompare(a)
    );
    return sortedYears.map((year) => ({ year, items: grouped.get(year)! }));
  }, [currentList, t.unknownYear]);

  return (
    <div className="w-full pt-2 px-2 sm:px-10">
      <div className="flex flex-wrap gap-1 text-xs font-bold pb-4">
        {tags.name.map((tag) => {
          return (
            <span
              key={`live-tag-${tag}`}
              className={`px-2 py-1 tracking-wide rounded-md border cursor-pointer transition-colors ${
                currentNames.includes(tag)
                  ? "bg-bx-yellow text-bx-bg border-bx-yellow"
                  : "border-bx-line text-bx-ink hover:border-bx-blue"
              }`}
              onClick={() => handleNameTagClick(tag)}
            >
              #{tag}
            </span>
          );
        })}
        <br />
        {tags.year.map((tag) => {
          return (
            <span
              key={`live-tag-${tag}`}
              className={`px-2 py-1 tracking-wide rounded-md border cursor-pointer transition-colors ${
                currentYears.includes(tag)
                  ? "bg-bx-yellow text-bx-bg border-bx-yellow"
                  : "border-bx-line text-bx-ink hover:border-bx-blue"
              }`}
              onClick={() => handleYearTagClick(tag)}
            >
              #{tag}
            </span>
          );
        })}
        <br />
        {tags.type.map((tag) => {
          return (
            <span
              key={`live-tag-${tag}`}
              className={`px-2 py-1 tracking-wide rounded-md border cursor-pointer transition-colors ${
                currentTypes.includes(tag)
                  ? "bg-bx-yellow text-bx-bg border-bx-yellow"
                  : "border-bx-line text-bx-ink hover:border-bx-blue"
              }`}
              onClick={() => handleTypeTagClick(tag)}
            >
              #{tag === "event" ? t.tagEvent : t.tagOneman}
            </span>
          );
        })}
      </div>
      <p className="text-xs text-right text-bx-ink2">{t.count(currentList.length)}</p>

      {/* 年ジャンプ索引(スティッキー) */}
      {groupedByYear.length > 1 && (
        <div className="sticky top-0 z-20 -mx-2 sm:-mx-10 px-2 sm:px-10 py-2 bg-bx-bg/90 backdrop-blur border-b border-bx-line overflow-x-auto whitespace-nowrap">
          {groupedByYear.map(({ year }) => (
            <a
              key={`live-year-jump-${year}`}
              href={`#live-year-${year}`}
              className="inline-block px-2 py-1 mr-1 text-xs font-bold rounded-md text-bx-ink3 hover:text-bx-blue hover:bg-bx-surface/5 transition-colors"
            >
              {year}
            </a>
          ))}
        </div>
      )}

      <div style={{ isolation: "isolate" }}>
        {groupedByYear.map(({ year, items }) => (
          <div key={`live-year-${year}`}>
            <h2
              id={`live-year-${year}`}
              className="scroll-mt-24 pt-6 pb-2 text-2xl sm:text-3xl font-bold text-bx-ink"
            >
              {year}
              <span className="ml-2 text-xs sm:text-sm font-normal align-middle text-bx-ink3">
                {t.count(items.length)}
              </span>
            </h2>
            <Timeline theme={timelineRootTheme}>
              {items.map((live) => (
                <EnhancedLiveTimelineItem key={`timeline-item-${live.liveUuid}`} live={live} />
              ))}
            </Timeline>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Live;
